// Generated by xunchi-agent-centos7/tools/build_branding.py.
// TUI rendition of the supplied company mark; the reference PNG is retained.
import { RGBA } from "@opentui/core"
import { useTerminalDimensions } from "@opentui/solid"
import { For, Show } from "solid-js"
import { useTheme } from "../context/theme"

const brand = {
  "product": "xunchi-IC-agent",
  "company_zh": "苏州迅驰信息科技有限公司",
  "company_en": "Suzhou Xunchi Information Technology Co., Ltd",
  "subtitle": "集成电路设计助手",
  "colors": {
    "cyan": "#2BB3DE",
    "blue": "#2388BF"
  },
  "full_layout_min_columns": 76,
  "mark_min_columns": 58
}
const pixels = [
  "......................",
  "bccb.......bbb.bbb....",
  "bcccb.....bbbb.bbbbb..",
  ".ccccc...bbbbb.bbbbbb.",
  "..bcccb.bcbb.....bbbb.",
  "...ccccbccb.......bbb.",
  "....ccccccb........bb.",
  "....cccccc............",
  "....cccccc............",
  "....ccccccb...........",
  "...ccccbccc.......bbb.",
  "..ccccc.cccb.....bbbb.",
  ".ccccc..bccccb.bbbbbb.",
  "bccccb...ccccb.cccbb..",
  "bccc......bccb.ccbb...",
  ".b...........b.b......"
]
const pairs = Array.from({ length: pixels.length / 2 }, (_, index) => index * 2)

export function Logo() {
  const { theme } = useTheme()
  const dimensions = useTerminalDimensions()
  const palette = {
    c: RGBA.fromHex(brand.colors.cyan),
    b: RGBA.fromHex(brand.colors.blue),
  }
  const color = (pixel: string) => (pixel === "c" ? palette.c : pixel === "b" ? palette.b : theme.background)
  return (
    <box alignItems="center" gap={1}>
      <box flexDirection="row" gap={2}>
        <Show when={dimensions().width >= brand.mark_min_columns}>
          <box>
            <For each={pairs}>
              {(row) => (
                <box flexDirection="row">
                  <For each={Array.from(pixels[row])}>
                    {(top, index) => (
                      <text fg={color(top)} bg={color(pixels[row + 1][index()])} selectable={false}>
                        {"▀"}
                      </text>
                    )}
                  </For>
                </box>
              )}
            </For>
          </box>
        </Show>
        <box justifyContent="center" gap={1}>
          <Show when={dimensions().width >= 34}>
            <text fg={theme.text} selectable={false}>{brand.company_zh}</text>
          </Show>
          <Show when={dimensions().width >= brand.full_layout_min_columns}>
            <text fg={theme.textMuted} selectable={false}>{brand.company_en}</text>
          </Show>
          <text fg={palette.c} selectable={false}>{brand.product}</text>
        </box>
      </box>
      <Show when={dimensions().width >= 34}>
        <text fg={theme.textMuted} selectable={false}>{brand.subtitle}</text>
      </Show>
    </box>
  )
}
